package org.synqoria.scheduling;
import org.synqoria.security.TrustedAccessContext;import java.time.*;import java.util.*;
public class AppointmentAttendancePreflightTest{public static void main(String[]a){int n=0;var t=UUID.randomUUID();var f=UUID.randomUUID();var p=UUID.randomUUID();var b=new AppointmentAggregate(UUID.randomUUID(),t,f,p,UUID.randomUUID(),new AppointmentWindow(Instant.parse("2026-11-01T09:00:00Z"),Instant.parse("2026-11-01T10:00:00Z"),ZoneId.of("UTC")),AppointmentAggregate.State.CONFIRMED,2,null);var c=new TrustedAccessContext(t,f,UUID.randomUUID(),Set.of("appointment:manage"),Set.of(p));var s=new AppointmentAttendancePreflight();var arrival=s.prepare(c,b,2,AppointmentAggregate.State.ARRIVED,null);check(arrival.proposed().state()==AppointmentAggregate.State.ARRIVED);n++;check(arrival.event().aggregateVersion()==3);n++;check(s.prepare(c,b,2,AppointmentAggregate.State.NO_SHOW,null).outcome()==AppointmentAttendancePreflight.Outcome.INVALID_REASON);n++;check(s.prepare(c,b,2,AppointmentAggregate.State.NO_SHOW,"not present").proposed().state()==AppointmentAggregate.State.NO_SHOW);n++;check(!s.prepare(c,b,2,AppointmentAggregate.State.NO_SHOW,"not present").event().payloadSha256().equals(s.prepare(c,b,2,AppointmentAggregate.State.NO_SHOW,"another reason").event().payloadSha256()));n++;check(s.prepare(c,arrival.proposed(),3,AppointmentAggregate.State.FULFILLED,null).proposed().state()==AppointmentAggregate.State.FULFILLED);n++;check(s.prepare(c,b,2,AppointmentAggregate.State.FULFILLED,null).outcome()==AppointmentAttendancePreflight.Outcome.INVALID_TRANSITION);n++;check(s.prepare(c,b,9,AppointmentAggregate.State.ARRIVED,null).outcome()==AppointmentAttendancePreflight.Outcome.STALE);n++;check(s.prepare(null,b,2,AppointmentAggregate.State.ARRIVED,null).proposed()==null);n++;System.out.println("PASS "+n+" attendance assertions");}static void check(boolean b){if(!b)throw new AssertionError();}}
